// Command CloudflareIdentity-cli is a CLI + REPL for the CloudflareIdentity SDK,
// built on the boru engine. Positional arguments are joined into a
// single boru expression and evaluated; with no arguments, falls into
// a REPL. Generated by sdkgen go-cli target.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	eng "github.com/boru-lang/boru/eng/go"
	"github.com/boru-lang/boru/eng/go/parser"
	sdk "github.com/voxgig-sdk/cloudflare-identity-sdk/go"
)

// prompt is the REPL prompt prefix (matches the SDK slug).
const prompt = "cloudflare-identity"

// entitiesHelp is the space-separated entity list shown by /help.
const entitiesHelp = "aaa_audit_logs_v2_org_history_response_collection aaa_audit_logs_v2_org_response_collection account account_resource_group account_user_group account_user_group_member begin_verification bill_subs_api_client_secret_response_single billable_usage_api_v2_usage dns_custom_nameservers_empty_response_3 dns_custom_nameservers_tcns_response_collection dns_custom_nameservers_tcns_response_single iam_api_response_single_id iam_collection_member_response_with_policy iam_collection_oauth_client iam_collection_oauth_scope iam_collection_organization iam_collection_permission_group iam_collection_role iam_collection_token iam_oauth_client_rotate_secret iam_permissions_group_response_collection iam_response_single_value iam_schemas_collection_invite iam_single_invite iam_single_member_response_with_policy iam_single_membership_response_with_policy iam_single_oauth_client iam_single_oauth_client_create iam_single_organization iam_single_permission_group iam_single_role iam_single_token iam_single_token_create iam_sso_connector iam_sso_connector_collection iam_token_verify_response_single_segment member oauth_client organization organization_member organizations_api_profile resource resource_group resource_sharing resource_sharing_share_excluded_recipient_response_collection resource_sharing_share_excluded_recipient_response_single resource_sharing_share_recipient_response_collection resource_sharing_share_recipient_response_single resource_sharing_share_response_collection resource_sharing_share_response_single scim_discovery scim_group scim_user sso_connector tenant token user user_group users_account_membership users_organization"

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

// usage prints the CLI help (for --help / -h). No client or network setup.
func usage(out io.Writer) {
	fmt.Fprintf(out, "%s-cli — boru-driven CLI + REPL for the %s SDK\n\n", prompt, prompt)
	fmt.Fprintln(out, "Usage:")
	fmt.Fprintf(out, "  %s-cli [--help] [<boru expression>]\n\n", prompt)
	fmt.Fprintln(out, "With arguments, they are joined into a single boru expression and")
	fmt.Fprintln(out, "evaluated against the API. With no arguments, starts an interactive REPL.")
	fmt.Fprintln(out)
	fmt.Fprintln(out, "Words:    list / load / update <query?> <entity>")
	fmt.Fprintln(out, "Entities:", entitiesHelp)
	fmt.Fprintln(out, "Env:      CLOUDFLARE_IDENTITY_APIKEY (api key), CLOUDFLARE_IDENTITY_BASE (base url override)")
	fmt.Fprintln(out, "REPL:     /help  /quit")
}

func run(args []string, in io.Reader, out, errOut io.Writer) int {
	// --help / -h: print usage and exit before any config or network setup.
	for _, a := range args {
		if a == "--help" || a == "-h" {
			usage(out)
			return 0
		}
	}

	// Configure from the environment: CLOUDFLARE_IDENTITY_APIKEY carries the API key and
	// CLOUDFLARE_IDENTITY_BASE optionally overrides the API base URL (e.g. production).
	// Both injectable by a secrets vault. Unset -> nil config defaults.
	var opts map[string]any
	if apikey := os.Getenv("CLOUDFLARE_IDENTITY_APIKEY"); apikey != "" {
		opts = map[string]any{"apikey": apikey}
	}
	if base := os.Getenv("CLOUDFLARE_IDENTITY_BASE"); base != "" {
		if opts == nil {
			opts = map[string]any{}
		}
		opts["base"] = base
	}
	client := sdk.NewCloudflareIdentitySDK(opts)

	r, err := eng.NewRegistry()
	if err != nil {
		fmt.Fprintf(errOut, "registry: %v\n", err)
		return 1
	}
	registerSDKWords(r, client)
	if err := r.Err(); err != nil {
		fmt.Fprintf(errOut, "word registration: %v\n", err)
		return 1
	}
	r.SetParseFunc(parser.Parse)
	r.InitRootContext()
	r.MarkReady()

	if len(args) > 0 {
		return evalOnce(r, strings.Join(args, " "), out, errOut)
	}
	repl(r, in, out)
	return 0
}

func evalOnce(r *eng.Registry, src string, out, errOut io.Writer) int {
	values, err := parser.Parse(src)
	if err != nil {
		fmt.Fprintf(errOut, "parse: %v\n", err)
		return 1
	}
	result, err := eng.NewTop(r).Run(values)
	if err != nil {
		fmt.Fprintf(errOut, "error: %v\n", err)
		return 1
	}
	for _, v := range result {
		fmt.Fprintln(out, v.String())
	}
	return 0
}

func repl(r *eng.Registry, in io.Reader, out io.Writer) {
	scanner := bufio.NewScanner(in)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for {
		fmt.Fprintf(out, "%s> ", prompt)
		if !scanner.Scan() {
			fmt.Fprintln(out)
			return
		}
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		switch line {
		case "/quit", "/q", "/exit":
			return
		case "/help", "/h", "/?":
			fmt.Fprintln(out, "words:    list / load / update <query?> <entity>")
			fmt.Fprintln(out, "entities:", entitiesHelp)
			fmt.Fprintln(out, "meta:     /help  /quit")
			continue
		}
		values, err := parser.Parse(line)
		if err != nil {
			fmt.Fprintf(out, "  parse error: %v\n", err)
			continue
		}
		result, err := eng.NewTop(r).Run(values)
		if err != nil {
			fmt.Fprintf(out, "  error: %v\n", err)
			continue
		}
		for _, v := range result {
			fmt.Fprintln(out, v.String())
		}
	}
}
